package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Validate inputs - reject empty values
	if loadBalancerName == "" {
		return "", fmt.Errorf("loadBalancerName cannot be empty")
	}
	if outputFile == "" {
		return "", fmt.Errorf("outputFile cannot be empty")
	}

	// Create the aliyun command - arguments are passed directly, avoiding shell injection
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Create the jq command
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe between aliyun and jq
	aliyunStdout, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe for aliyun command: %w", err)
	}

	// Set jq's stdin to read from aliyun's stdout
	jqCmd.Stdin = aliyunStdout

	// Capture jq's output
	var jqStdout bytes.Buffer
	var jqStderr bytes.Buffer
	jqCmd.Stdout = &jqStdout
	jqCmd.Stderr = &jqStderr

	// Capture aliyun's stderr
	var aliyunStderr bytes.Buffer
	aliyunCmd.Stderr = &aliyunStderr

	// Start aliyun command
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start jq command
	if err := jqCmd.Start(); err != nil {
		aliyunCmd.Process.Kill()
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for aliyun to complete
	aliyunErr := aliyunCmd.Wait()

	// Wait for jq to complete
	jqErr := jqCmd.Wait()

	// Get the output
	outputStr := jqStdout.String()

	// Check for errors
	if aliyunErr != nil {
		return outputStr, fmt.Errorf("aliyun command failed: %w, stderr: %s", aliyunErr, aliyunStderr.String())
	}

	if jqErr != nil {
		return outputStr, fmt.Errorf("jq command failed: %w, stderr: %s", jqErr, jqStderr.String())
	}

	// Write output to file
	outFile, err := os.Create(outputFile)
	if err != nil {
		return outputStr, fmt.Errorf("failed to create output file: %w", err)
	}
	defer outFile.Close()

	_, err = io.WriteString(outFile, outputStr)
	if err != nil {
		return outputStr, fmt.Errorf("failed to write to output file: %w", err)
	}

	return outputStr, nil
}

func main() {
	// Example usage
	result, err := QuerySLBAndExport("my-slb-name", "output.json")
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Result: %s\n", result)
}

