	}

	if loadBalancerName == "" {
		return "", fmt.Errorf("load balancer name cannot be empty")
	}

	// Validate and sanitize outputFile path
	if outputFile == "" {
		return "", fmt.Errorf("output file path cannot be empty")
	}

	// Clean the path and ensure it's not trying to escape to unexpected locations
	cleanedPath := filepath.Clean(outputFile)

	// Prevent absolute paths or path traversal attempts
	if filepath.IsAbs(cleanedPath) {
		return "", fmt.Errorf("absolute paths are not allowed for output file")
	}

	// Check for path traversal attempts
	if containsPathTraversal(cleanedPath) {
