package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Validate loadBalancerName using allowlist approach
	// SLB names typically contain alphanumeric characters, hyphens, and underscores
	validNamePattern := regexp.MustCompile(`^[a-zA-Z0-9_-]+$`)
	if !validNamePattern.MatchString(loadBalancerName) {
		return "", fmt.Errorf("invalid load balancer name: must contain only alphanumeric characters, hyphens, and underscores")
	}

	if loadBalancerName == "" {
		return "", fmt.Errorf("load balancer name cannot be empty")
	}

	// Validate and sanitize outputFile path
	if outputFile == "" {
		return "", fmt.Errorf("output file path cannot be empty")
	}

	// Clean the path to prevent path traversal
	cleanPath := filepath.Clean(outputFile)

	// Ensure the path doesn't escape to parent directories
	if filepath.IsAbs(cleanPath) {
		// For absolute paths, ensure it's within expected directories
		// You may want to restrict to specific directories
	} else {
		// For relative paths, ensure no parent directory traversal
		if cleanPath != outputFile || filepath.HasPrefix(cleanPath, "..") {
			return "", fmt.Errorf("invalid output file path: path traversal detected")
		}
	}

	// Validate file extension
	if filepath.Ext(cleanPath) != ".json" {
		return "", fmt.Errorf("output file must have .json extension")
	}

	// Execute aliyun command directly without shell
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Capture aliyun command output
	var aliyunStdout bytes.Buffer
	var aliyunStderr bytes.Buffer
	aliyunCmd.Stdout = &aliyunStdout
	aliyunCmd.Stderr = &aliyunStderr

	if err := aliyunCmd.Run(); err != nil {
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", err, aliyunStderr.String())
	}

	// Execute jq command directly without shell
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
	jqCmd.Stdin = &aliyunStdout

	var jqStdout bytes.Buffer
	var jqStderr bytes.Buffer
	jqCmd.Stdout = &jqStdout
	jqCmd.Stderr = &jqStderr

	if err := jqCmd.Run(); err != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", err, jqStderr.String())
	}

	// Write output to file securely
	// Use O_CREATE|O_WRONLY|O_TRUNC with restricted permissions
	file, err := os.OpenFile(cleanPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
	if err != nil {
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer file.Close()

	result := jqStdout.String()
	if _, err := io.WriteString(file, result); err != nil {
		return "", fmt.Errorf("failed to write to output file: %w", err)
	}

	return result, nil
}

func main() {
	// Example usage
	result, err := QuerySLBAndExport("my-load-balancer", "output.json")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	fmt.Println("Result:", result)
}

