package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// QuerySLBAndExport queries SLB information using aliyun CLI and exports it using jq
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Build the command pipeline: aliyun slb DescribeLoadBalancers --LoadBalancerName NAME | jq '.LoadBalancers.LoadBalancer[]'
	// We use sh -c to execute the pipeline

	// Escape the loadBalancerName to prevent command injection
	escapedName := strings.ReplaceAll(loadBalancerName, "'", "'\"'\"'")

	// Build the full command
	cmdStr := fmt.Sprintf("aliyun slb DescribeLoadBalancers --LoadBalancerName '%s' | jq '.LoadBalancers.LoadBalancer[]'", escapedName)

	// Execute the command using sh -c
	cmd := exec.Command("sh", "-c", cmdStr)

	// Capture the output
	output, err := cmd.Output()
	if err != nil {
		// Try to get stderr for more detailed error information
		if exitErr, ok := err.(*exec.ExitError); ok {
			return "", fmt.Errorf("command execution failed: %v, stderr: %s", err, string(exitErr.Stderr))
		}
		return "", fmt.Errorf("command execution failed: %v", err)
	}

	// Write the output to the specified file
	err = os.WriteFile(outputFile, output, 0644)
	if err != nil {
		return "", fmt.Errorf("failed to write output file: %v", err)
	}

	result := string(output)
	return result, nil
}

func main() {
	// Example usage
	loadBalancerName := "my-slb"
	outputFile := "output.json"

	// Check if command line arguments are provided
	if len(os.Args) >= 3 {
		loadBalancerName = os.Args[1]
		outputFile = os.Args[2]
	}

	fmt.Printf("Querying SLB with name: %s\n", loadBalancerName)
	fmt.Printf("Output file: %s\n", outputFile)

	result, err := QuerySLBAndExport(loadBalancerName, outputFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Println("Query successful!")
	fmt.Println("Result:")
	fmt.Println(result)
}

