package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the processed output and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Validate inputs to prevent shell injection
	// Check for characters that could be used for injection
	invalidChars := "`$\n\r\t|><;&(){}[]!#"
	if strings.ContainsAny(loadBalancerName, invalidChars) {
		return "", fmt.Errorf("invalid characters in loadBalancerName")
	}
	if strings.ContainsAny(outputFile, invalidChars) {
		return "", fmt.Errorf("invalid characters in outputFile")
	}

	// Also check for single quote which could break shell quoting
	if strings.Contains(loadBalancerName, "'") {
		return "", fmt.Errorf("invalid characters in loadBalancerName")
	}
	if strings.Contains(outputFile, "'") {
		return "", fmt.Errorf("invalid characters in outputFile")
	}

	// Validate that outputFile is not empty
	if outputFile == "" {
		return "", fmt.Errorf("outputFile cannot be empty")
	}

	// Execute aliyun command directly without shell
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Execute jq command
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create pipe between aliyun and jq
	var aliyunStderr bytes.Buffer
	aliyunCmd.Stderr = &aliyunStderr

	// Get stdout pipe from aliyun command
	aliyunStdout, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe for aliyun command: %w", err)
	}

	// Connect aliyun stdout to jq stdin
	jqCmd.Stdin = aliyunStdout

	// Capture jq output
	var jqStdout, jqStderr bytes.Buffer
	jqCmd.Stdout = &jqStdout
	jqCmd.Stderr = &jqStderr

	// Start aliyun command
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start jq command
	if err := jqCmd.Start(); err != nil {
		aliyunCmd.Process.Kill()
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for aliyun to complete
	aliyunErr := aliyunCmd.Wait()

	// Wait for jq to complete
	jqErr := jqCmd.Wait()

	// Check for errors
	if aliyunErr != nil {
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", aliyunErr, aliyunStderr.String())
	}

	if jqErr != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", jqErr, jqStderr.String())
	}

	// Get the output
	output := jqStdout.String()

	// Write output to file
	if err := os.WriteFile(outputFile, jqStdout.Bytes(), 0644); err != nil {
		return output, fmt.Errorf("failed to write output file: %w", err)
	}

	return output, nil
}

func main() {
	// Example usage
	result, err := QuerySLBAndExport("my-slb-name", "output.json")
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Output: %s\n", result)
}

