// validateLoadBalancerName validates the load balancer name using an allowlist approach
// Typically, load balancer names contain alphanumeric characters, hyphens, and underscores
func validateLoadBalancerName(name string) error {
	if name == "" {
		return fmt.Errorf("load balancer name cannot be empty")
	}
	if len(name) > 256 {
		return fmt.Errorf("load balancer name too long")
	}
	// Allowlist: alphanumeric, hyphens, underscores, and dots
	validPattern := regexp.MustCompile(`^[a-zA-Z0-9_\-\.]+$`)
