	}
	return nil
}

// validateOutputFile validates the output file path
func validateOutputFile(outputFile string) error {
	if outputFile == "" {
		return fmt.Errorf("output file cannot be empty")
	}

	// Clean the path to prevent directory traversal
	cleanPath := filepath.Clean(outputFile)

	// Ensure it's not an absolute path trying to write to sensitive locations
	// or contains directory traversal
	if filepath.IsAbs(cleanPath) {
		// For absolute paths, ensure they're in expected directories
		// This is a basic check - adjust based on your requirements
