func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Validate loadBalancerName - allow only alphanumeric, hyphens, and underscores
	// Adjust the pattern based on actual SLB naming conventions
	validNamePattern := regexp.MustCompile(`^[a-zA-Z0-9_-]+$`)
	if !validNamePattern.MatchString(loadBalancerName) {
		return "", fmt.Errorf("invalid load balancer name: must contain only alphanumeric characters, hyphens, and underscores")
	}

	if loadBalancerName == "" {
		return "", fmt.Errorf("load balancer name cannot be empty")
	}

	// Validate and sanitize output file path
	if outputFile == "" {
		return "", fmt.Errorf("output file path cannot be empty")
	}

	// Clean the path to prevent path traversal
	cleanPath := filepath.Clean(outputFile)

	// Ensure the path doesn't escape to parent directories in an unsafe way
	// Convert to absolute path for validation
	absPath, err := filepath.Abs(cleanPath)
	if err != nil {
		return "", fmt.Errorf("invalid output file path: %w", err)
	}

	// Ensure the file has a safe extension
	if filepath.Ext(absPath) != ".json" {
		return "", fmt.Errorf("output file must have .json extension")
	}

	// Ensure the directory exists and is writable
	dir := filepath.Dir(absPath)
	if _, err := os.Stat(dir); os.IsNotExist(err) {
		return "", fmt.Errorf("output directory does not exist: %s", dir)
	}

	// Create the aliyun command - pass arguments directly, no shell
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Create the jq command - pass arguments directly, no shell
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Set up the pipe between aliyun and jq
	aliyunStdout, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe for aliyun command: %w", err)
	}

	// Capture stderr from aliyun command
	var aliyunStderr bytes.Buffer
	aliyunCmd.Stderr = &aliyunStderr

	// Connect aliyun stdout to jq stdin
	jqCmd.Stdin = aliyunStdout

	// Capture jq output
	var jqStdout bytes.Buffer
	var jqStderr bytes.Buffer
	jqCmd.Stdout = &jqStdout
	jqCmd.Stderr = &jqStderr

	// Start aliyun command
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start jq command
	if err := jqCmd.Start(); err != nil {
		aliyunCmd.Process.Kill()
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for aliyun to complete
	aliyunErr := aliyunCmd.Wait()

	// Wait for jq to complete
	jqErr := jqCmd.Wait()

	// Check for errors
	if aliyunErr != nil {
